<?php error_reporting(E_ALL); ini_set("display_errors", "1"); session_start(); echo "<h2>Session Debug</h2>"; echo "<pre>"; print_r($_SESSION); echo "</pre>"; // Check login status if (!isset($_SESSION["user_id"])) { echo "No user_id found in session."; exit(); } echo "User ID: "; echo htmlspecialchars( (string) $_SESSION["user_id"], ENT_QUOTES, "UTF-8" ); echo "<br><br>"; echo "Username: "; if (isset($_SESSION["username"])) { echo htmlspecialchars( (string) $_SESSION["username"], ENT_QUOTES, "UTF-8" ); } else { echo "USERNAME IS NOT SET"; } ?>